mapper.select:
SELECT app.application_id, app.announcement_id, a.title AS announcement_title, app.company_user_id, u.company_name, u.business_no, app.project_name, app.total_budget, app.request_grant, app.self_funding, app.summary, app.plan_file_name, app.status, c.code_name AS status_name, app.submitted_at, app.created_at, e.total_score FROM application app INNER JOIN announcement a ON app.announcement_id = a.announcement_id INNER JOIN users u ON app.company_user_id = u.user_id LEFT JOIN com_code_detail c ON app.status = c.code_id AND c.group_id = 'APP_STATUS' LEFT JOIN evaluation e ON app.application_id = e.application_id
AND app.announcement_id = #{announcementId}
AND app.company_user_id = #{companyUserId}
AND app.status = #{status}
ORDER BY app.application_id DESC

mapper.insert:
INSERT INTO application (
    announcement_id, company_user_id, project_name, total_budget, request_grant, self_funding, summary, plan_file_name, status, submitted_at
) VALUES (
    #{announcementId}, #{companyUserId}, #{projectName}, #{totalBudget}, #{requestGrant}, #{selfFunding}, #{summary}, #{planFileName}, #{status}, CURRENT_TIMESTAMP
)

mapper.update:
UPDATE application
SET status = #{status}
WHERE application_id = #{applicationId}
